using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Quotations.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Enums;namespace Namaa.Application.Quotations.Commands.AddQuotationPaymentTerm;public sealed class AddQuotationPaymentTermCommandHandler(IQuotationRepository repository,IApplicationDbContext db):IRequestHandler<AddQuotationPaymentTermCommand,Result<QuotationPaymentTermDto>>{public async Task<Result<QuotationPaymentTermDto>>Handle(AddQuotationPaymentTermCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.QuotationId,cancellationToken);if(e is null)return Result.Failure<QuotationPaymentTermDto>(QuotationErrors.NotFound);if(e.Status!=QuotationStatus.Draft)return Result.Failure<QuotationPaymentTermDto>(QuotationErrors.NotDraft);var term=e.AddPaymentTerm(request.Percentage,request.Amount,request.Description,request.DueAfterDays,request.DueDate);await db.SaveChangesAsync(cancellationToken);return Result.Success(QuotationPaymentTermDto.FromEntity(term));}}

